35	class InitProjectGenerationRequestFactory {
36	
37		private final InitCommandOptionDefinitions options;
38	
39		InitProjectGenerationRequestFactory(InitCommandOptionDefinitions options) {
40			this.options = options;
41		}
42	
43		ProjectGenerationRequest create(OptionSet options) {
44			List<?> nonOptionArguments = new ArrayList<>(options.nonOptionArguments());
45			Assert.state(nonOptionArguments.size() <= 1, "Only the target location may be specified");
46			ProjectGenerationRequest request = new ProjectGenerationRequest();
47			request.setServiceUrl(options.valueOf(this.options.getTargetOption()));
48			applyConfiguredValue(options, this.options.getBootVersionOption(), request::setBootVersion);
49			applyConfiguredDependencies(options, request);
50			applyConfiguredValue(options, this.options.getJavaVersionOption(), request::setJavaVersion);
51			applyConfiguredValue(options, this.options.getPackageNameOption(), request::setPackageName);
52			request.setBuild(options.valueOf(this.options.getBuildOption()));
53			request.setFormat(options.valueOf(this.options.getFormatOption()));
54			request.setDetectType(options.has(this.options.getBuildOption()) || options.has(this.options.getFormatOption()));
55			applyConfiguredValue(options, this.options.getTypeOption(), request::setType);
56			applyConfiguredValue(options, this.options.getPackagingOption(), request::setPackaging);
57			applyConfiguredValue(options, this.options.getLanguageOption(), request::setLanguage);
58			applyConfiguredValue(options, this.options.getGroupIdOption(), request::setGroupId);
59			applyConfiguredValue(options, this.options.getArtifactIdOption(), request::setArtifactId);
60			applyConfiguredValue(options, this.options.getNameOption(), request::setName);
61			applyConfiguredValue(options, this.options.getVersionOption(), request::setVersion);
62			applyConfiguredValue(options, this.options.getDescriptionOption(), request::setDescription);
63			request.setExtract(options.has(this.options.getExtractOption()));
64			if (nonOptionArguments.size() == 1) {
65				String output = (String) nonOptionArguments.get(0);
66				request.setOutput(output);
67			}
68			return request;
69		}
70	
71		private void applyConfiguredDependencies(OptionSet options, ProjectGenerationRequest request) {
72			OptionSpec<String> dependencies = this.options.getDependenciesOption();
73			if (!options.has(dependencies)) {
74				return;
75			}
76			for (String dependency : options.valueOf(dependencies).split(",")) {
77				request.getDependencies().add(dependency.trim());
78			}
79		}
80	
81		private void applyConfiguredValue(OptionSet options, OptionSpec<String> option, Consumer<String> setter) {
82			if (options.has(option)) {
83				setter.accept(options.valueOf(option));
84			}
85		}
