24	/**
25	 * Rewrites camelCase CLI arguments to the kebab-case options understood by
26	 * {@link InitCommand}.
27	 *
28	 * @author Stephane Nicoll
29	 * @author Eddú Meléndez
30	 * @author Vignesh Thangavel Ilangovan
31	 */
32	class InitCommandArgumentProcessor implements Function<String, String> {
33	
34		private static final Map<String, String> CAMEL_CASE_OPTIONS;
35		static {
36			Map<String, String> options = new HashMap<>();
37			options.put("--groupId", "--group-id");
38			options.put("--artifactId", "--artifact-id");
39			options.put("--packageName", "--package-name");
40			options.put("--javaVersion", "--java-version");
41			options.put("--bootVersion", "--boot-version");
42			CAMEL_CASE_OPTIONS = Collections.unmodifiableMap(options);
43		}
44	
45		@Override
46		public String apply(String argument) {
47			for (Map.Entry<String, String> entry : CAMEL_CASE_OPTIONS.entrySet()) {
48				String name = entry.getKey();
49				if (argument.startsWith(name + " ") || argument.startsWith(name + "=")) {
50					return entry.getValue() + argument.substring(name.length());
51				}
52			}
53			return argument;
54		}
55	
56	}

